/*
 * Publish the embedded AIC8800 firmware (aicwf_fw_data.c, generated by fetch-firmware.sh)
 * as read-only files under AIC8800_WIFI_FIRMWARE_PATH, where the RT-Smart loader opens
 * them with open()/read(). IMFS linear files point at the constant data: no copy.
 *
 * SPDX-License-Identifier: Apache-2.0
 */
#include <rtthread.h>
#include <dfs_posix.h>

#include "aicwf_shim.h"

#ifdef __rtems__
#include <rtems/imfs.h>
#endif

#define DBG_TAG "aicwf.fw"
#define DBG_LVL DBG_INFO
#include <rtdbg.h>

struct aicwf_fw_file {
    const char *path;
    const uint8_t *data;
    size_t size;
};

extern const struct aicwf_fw_file aicwf_fw_files[];
extern const size_t aicwf_fw_file_count;

static int mkdir_p(const char *path)
{
    char buf[256];
    size_t i, len = strlen(path);

    if (len >= sizeof(buf))
    {
        return -1;
    }
    memcpy(buf, path, len + 1);
    for (i = 1; i <= len; i++)
    {
        if (buf[i] == '/' || buf[i] == '\0')
        {
            char c = buf[i];

            buf[i] = '\0';
            if (mkdir(buf, 0755) != 0 && errno != EEXIST)
            {
                return -1;
            }
            buf[i] = c;
        }
    }
    return 0;
}

int aicwf_fw_install(void)
{
    char path[256];
    size_t i, installed = 0, bytes = 0;

    if (aicwf_fw_file_count == 0)
    {
        LOG_W("no AIC8800 firmware in this image (fetch-firmware.sh was not run)");
        return -1;
    }
    for (i = 0; i < aicwf_fw_file_count; i++)
    {
        const struct aicwf_fw_file *file = &aicwf_fw_files[i];
        const char *slash = strrchr(file->path, '/');

        snprintf(path, sizeof(path), "%s/%s", AIC8800_WIFI_FIRMWARE_PATH, file->path);
        if (slash)
        {
            char dir[256];

            snprintf(dir, sizeof(dir), "%s/%.*s", AIC8800_WIFI_FIRMWARE_PATH,
                     (int)(slash - file->path), file->path);
            if (mkdir_p(dir) != 0)
            {
                LOG_E("cannot create %s (%d)", dir, errno);
                return -1;
            }
        }
#ifdef __rtems__
        if (IMFS_make_linearfile(path, 0444, file->data, file->size) != 0 && errno != EEXIST)
        {
            LOG_E("cannot publish %s (%d)", path, errno);
            return -1;
        }
#else
        {
            /* host test builds: plain files */
            int fd = open(path, O_CREAT | O_WRONLY | O_TRUNC, 0644);

            if (fd < 0 || write(fd, file->data, file->size) != (ssize_t)file->size)
            {
                LOG_E("cannot write %s", path);
                if (fd >= 0)
                {
                    close(fd);
                }
                return -1;
            }
            close(fd);
        }
#endif
        installed++;
        bytes += file->size;
    }
    LOG_I("%u firmware files (%u bytes) under %s", (unsigned)installed, (unsigned)bytes,
          AIC8800_WIFI_FIRMWARE_PATH);
    return 0;
}
